SELECT ,

FROM wm_stock_document d
WHERE d.direction=#{query.direction}
AND d.document_type=#{query.documentType}
AND d.status=#{query.status}
AND d.document_no LIKE CONCAT('%',#{query.documentNo},'%')
AND EXISTS (
 SELECT 1 FROM wm_stock_document_line l
 JOIN wm_inventory s ON s.id=l.stock_id
 WHERE l.document_id=d.id
 AND s.id=#{query.stockId}
 AND l.material_id=#{query.materialId}
 AND l.batch_no LIKE CONCAT('%',#{query.batchNo},'%')
 AND l.bin_code LIKE CONCAT('%',#{query.binCode},'%')
)
ORDER BY d.id DESC

SELECT audit_id FROM ( SELECT DISTINCT d.post_request_id AS audit_id,d.posted_at AS posted_at,d.id AS document_id
AND () UNION ALL SELECT DISTINCT d.post_request_id AS audit_id,d.posted_at AS posted_at,d.id AS document_id FROM mes_quality_treatment t JOIN (
) proof ON proof.eventId=t.id AND proof.validCount=1 JOIN wm_stock_document d ON d.id=t.stock_document_id WHERE t.execution_code=#{executionCode} ) approved ORDER BY posted_at DESC,document_id DESC LIMIT 1




SELECT COALESCE(SUM(f.quantity),0) FROM (
 SELECT l.quantity FROM mes_production_execution e
 JOIN wm_stock_document d ON d.source_execution_code=e.execution_code AND d.status=#{posted} AND d.document_type IN (#{receipt},#{productionReceipt})
 JOIN wm_stock_document_line l ON l.document_id=d.id
 JOIN wm_stock_action a ON a.id=l.stock_action_id AND a.document_line_id=l.id AND a.execution_code=e.execution_code
 WHERE e.workorder_id=#{workorderId}
 UNION ALL
 SELECT a.quantity_delta FROM mes_warehouse_acceptance a JOIN mes_production_execution e ON e.execution_code=a.execution_code
 WHERE e.workorder_id=#{workorderId}
) f
